import tw.rex.link.ParentForm;
public class ParentFormTest {
 static int n;static void ok(boolean pass,String name){if(!pass)throw new AssertionError(name);n++;System.out.println("PASS "+name);}
 public static void main(String[] args){ok(ParentForm.integer(2,1)==2,"numeric grade preserved");ok(ParentForm.integer(" 2 ",1)==2,"legacy string grade read safely");ok(ParentForm.integer("bad",1)==1,"invalid numeric setting falls back");ok(ParentForm.integer(null,10)==10,"missing setting falls back");ok(ParentForm.integer(true,1)==1,"unexpected setting type does not throw");ok(ParentForm.string(30,"10").equals("30"),"legacy numeric seconds remain readable");ok(ParentForm.string(null,"10").equals("10"),"missing seconds have default");ok(ParentForm.bool("true",false),"string boolean enabled");ok(!ParentForm.bool("0",true),"string boolean disabled");ok(ParentForm.bool(true,false),"boolean preference preserved");ok(ParentForm.longValue("1760000000000",0)==1760000000000L,"lockout timestamp preserves precision");ok(ParentForm.selection(-1,2)==0,"negative picker selection clamps");ok(ParentForm.selection(20,7)==6,"out of range subject selection clamps");ok(ParentForm.selection(3,7)==3,"valid selection preserved");ok(ParentForm.selection(5,0)==0,"empty option list is safe");System.out.println(n+" checks passed");}
}
